// Fills every <nav class="sitenav" data-site-nav> with the site menu, so the
// menu lives in one place — including on the simulation editions, which are
// generated by model/build_pages.py and only carry the empty placeholder.
(function () {
  const PAGES = [
    ["/", "Take action", ["/", "/index.html"]],
    ["/faq", "FAQ", ["/faq", "/questions", "/questions.html"]],
    ["/examples", "Examples", ["/examples", "/examples.html"]],
    // Still being written: the tab only shows when the site is run locally.
    ...(/^(localhost|127\.0\.0\.1)$/.test(location.hostname)
        ? [["/concerns", "Concerns", ["/concerns", "/concerns.html"]]] : []),
    ["/crashes", "Crashes", ["/crashes", "/crashes.html"]],
    ["/safety", "Safety", ["/safety", "/safety.html"]],
    ["/traffic", "Traffic", ["/traffic", "/traffic.html", "/simulation", "/simulation.html",
                            "/buildup", "/build-up", "/short", "/public", "/full", "/detailed",
                            "/short.html", "/full.html"]],
    ["/emergency", "Emergencies", ["/emergency", "/emergency.html"]],
    ["/parking", "Parking & business", ["/parking", "/parking.html", "/business"]],
    ["/what-drives-traffic", "What drives traffic", ["/what-drives-traffic", "/what-drives-traffic.html"]],
    ["/process", "Process", ["/process", "/process.html"]],
  ];
  const here = location.pathname.replace(/\/+$/, "") || "/";
  const items = PAGES.map(([href, label, paths]) => {
    const cur = paths.includes(here) ? ' aria-current="page"' : "";
    const cls = href === "/" ? ' class="sitenav-act"' : "";
    return `<li><a href="${href}"${cls}${cur}>${label}</a></li>`;
  }).join("");
  const html =
    `<div class="sitenav-inner">` +
      `<a class="sitenav-brand" href="/"><b>Boston Post Road</b><span>Safe Routes to School</span></a>` +
      `<ul class="sitenav-links">${items}</ul>` +
    `</div>`;
  function fill() {
    document.querySelectorAll("nav[data-site-nav]").forEach(n => {
      // The simulation editions put the placeholder inside their padded
      // .wrap column; lift it out so the bar spans the page like elsewhere.
      if (n.parentElement !== document.body) document.body.prepend(n);
      n.innerHTML = html;
      n.setAttribute("aria-label", "Site");
      const cur = n.querySelector('[aria-current="page"]');
      if (cur) cur.scrollIntoView({ block: "nearest", inline: "center" });
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", fill);
  else fill();

  // ---- Analytics -----------------------------------------------------------
  // GoatCounter: no cookies, no device identifier, so no consent banner needed.
  // Put the site code here to switch it on; empty means off. Every page loads
  // this file, including the generated simulation editions, so this is the only
  // place it needs to go.
  const GOATCOUNTER = "bostonpostroadsafety";
  const LOCAL = /^(localhost|127\.0\.0\.1)$/.test(location.hostname);
  if (GOATCOUNTER && !LOCAL) {
    const s = document.createElement("script");
    s.async = true;
    s.src = "//gc.zgo.at/count.js";
    s.setAttribute("data-goatcounter", `https://${GOATCOUNTER}.goatcounter.com/count`);
    document.head.appendChild(s);

    // Count the things we actually care about, not only page views.
    const ACTIONS = [
      ["[data-petition]", "action-petition", "Signed the petition"],
      ["[data-email-gmail]", "action-email-gmail", "Opened the letter in Gmail"],
      ["[data-email]", "action-email", "Opened the letter in a mail app"],
      ["[data-copy-letter]", "action-copy-letter", "Copied the letter"],
      ['a[href$=".pdf"]', "download-pdf", "Opened a source document"],
    ];
    document.addEventListener("click", (e) => {
      for (const [sel, path, title] of ACTIONS) {
        if (e.target.closest(sel)) {
          window.goatcounter?.count({ path, title, event: true });
          return;
        }
      }
    });
  }
})();
